-- AKEMI JAPAN — JFT-Basic 50 soal original
-- Tambahkan/ulang seed JFT tanpa menyentuh Part lain.
alter table questions add column if not exists audio_text text;
DO $$
DECLARE
  pid uuid;
  pn int;
BEGIN
  -- Jika seed JFT pernah dipasang, hapus hanya Part JFT milik seed ini.
  DELETE FROM questions WHERE part_id IN (SELECT id FROM parts WHERE name = 'JFT-Basic — 50 Soal');
  DELETE FROM parts WHERE name = 'JFT-Basic — 50 Soal';

  SELECT n INTO pn
  FROM generate_series(1,20) AS n
  WHERE NOT EXISTS (SELECT 1 FROM parts p WHERE p.part_number=n)
  ORDER BY n
  LIMIT 1;

  IF pn IS NULL THEN
    RAISE EXCEPTION 'Tidak ada nomor Part kosong (1-20). Hapus/nonaktifkan satu Part terlebih dahulu.';
  END IF;

  VALUES(pn,'JFT-Basic — 50 Soal','Latihan JFT-Basic original: campuran teks, foto, dan audio. Semua soal pilihan ganda.',50,true,true,true)
  RETURNING id INTO pid;

END $$;
